def move_integer_naive(conn, board_id, issue_id, old_pos, new_pos):
    try:
        with conn.transaction():
            if new_pos < old_pos:
                conn.execute('UPDATE issues SET pos = pos + 1 WHERE board_id=%s AND pos>=%s AND pos<%s', (board_id, new_pos, old_pos))
            conn.execute('UPDATE issues SET pos = %s WHERE id=%s', (new_pos, issue_id))
    except Exception as exc:
        conn.rollback()
        raise RuntimeError(f'Lock contention or deadlock during reorder: {exc}')

def float_midpoint(prev_pos: float, next_pos: float) -> float:
    mid = (prev_pos + next_pos) / 2.0
    if mid == prev_pos or mid == next_pos:
        raise ValueError('IEEE-754 precision exhausted; re-indexing required')
    return mid

