def format_lexorank(bucket: int, value: str) -> str:
    if bucket not in (0, 1, 2):
        raise ValueError('Bucket must be 0, 1, or 2')
    return f'{bucket}|{value}:'

import random, time

def assign_rank_with_retry(repo, board_id, issue_id, left_id, right_id, max_retries=4):
    for attempt in range(max_retries):
        left_rank, right_rank = repo.fetch_neighbor_ranks(board_id, left_id, right_id)
        candidate = lexo_midpoint(left_rank, right_rank)
        try:
            repo.update_rank_cas(board_id, issue_id, candidate)
            return candidate
        except UniqueRankViolation:
            time.sleep(0.01 * (2 ** attempt) + random.uniform(0, 0.005))
    raise RuntimeError('Exceeded max retries on concurrent rank assignment')

def rebalance_step(repo, board_id, current_bucket, batch_size=200):
    next_bucket = (current_bucket + 1) % 3
    issues = repo.fetch_bucket_ordered(board_id, current_bucket, limit=batch_size)
    if not issues:
        return False
    step = 36 ** 4
    for idx, issue in enumerate(issues):
        new_rank = format_lexorank(next_bucket, encode_base36((idx + 1) * step, width=6))
        repo.compare_and_swap_rank(issue.id, expected=issue.rank, new_rank=new_rank)
    return True

def move_card_across_columns(conn, board_id, issue_id, target_status, left_rank, right_rank, expected_ver):
    new_rank = lexo_midpoint(left_rank, right_rank)
    with conn.transaction():
        updated = conn.execute(
            'UPDATE issues SET status=%s, rank=%s, version=version+1 WHERE id=%s AND board_id=%s AND version=%s',
            (target_status, new_rank, issue_id, board_id, expected_ver)
        )
        if updated.rowcount == 0:
            raise ConcurrentModificationError('Issue modified by another user')
    return new_rank
